# -*- coding: utf-8 -*-
"""Текстовый выпуск 6 (план E007): тело страницы lessons/ep06.html — транспортные средства.

Собирается tools/build.py: build импортирует этот модуль и вызывает render().
Части разделены маркером <!--AFTER-TICKETS-->: всё после него сайт показывает под билетами."""
from pdd.lessonkit import chat, lq, fig, gl
from figs import fig_tree, fig_scale, fig_tram

P = []
P.append(chat(
    ("m", "Транспортное средство — это машина. Что тут учить?"),
    ("a", "А велосипед? А прицеп? А электросамокат, на котором ты ездишь на работу?"),
    ("t", "Вот поэтому и учим. От того, в какой класс попадает твоя техника, зависит, с какого возраста на ней можно ездить, где и с какой скоростью, и кто кому уступает на перекрёстке.")))

# ---------- 1. ТС и механическое ТС ----------
P.append('<h2 id="ts">1. Транспортное средство и механическое ТС</h2>')
P.append(lq("Транспортное средство – устройство, движущееся по дорогам или предназначенное для движения по дорогам, которое передвигается с помощью двигателя или иной силы.", "ст. 5, п. 73"))
P.append('<p>Определение очень широкое. «Иная сила» — мускулы (велосипед), животные (' + gl("гужевой транспорт", "«колесное или бесколесное транспортное средство без двигателя, передвигающееся по дорогам при помощи силы упряжных животных» (ст. 5, п. 78)") + '), тягач (прицеп). Слово «предназначенное» делает ТС и стоящую машину, и прицеп без тягача.</p>')
P.append(lq("Механическое транспортное средство – оснащенное двигателем транспортное средство (самоход), кроме двухколесного электросамоката, велосипеда с подвесным двигателем и рельсового транспортного средства.", "ст. 5, п. 35"))
P.append('<p>Механическое — это «с двигателем», <b>но за тремя исключениями</b>: двухколесный электросамокат, велосипед с подвесным двигателем и всё рельсовое (трамвай). Мотор у них есть, а механическими ТС они не считаются. Это важно: множество правил адресовано именно «механическим ТС».</p>')
P.append('<p>Внутри механических — ' + gl("автомобиль", "«механическое транспортное средство, которое обычно используется для перевозки по дорогам людей либо грузов» (ст. 5, п. 5); троллейбус сюда входит, трактор — нет") + '. Закон прямо называет троллейбус автомобилем, а трактор — нет: для трактора перевозка лишь «вспомогательной функцией». Троллейбусы и трамваи вместе — наземный электротранспорт (ст. 5, п. 40).</p>')
P.append(fig(fig_tree(), "Рис. 1. Дерево определений ст. 5. Красные — техника с мотором, которую п. 35 исключил из «механических»."))
P.append(chat(("m", "Получается, мой электросамокат — не механическое ТС, но транспортное средство?"),
              ("t", "Да. Двигатель у него есть, значит по п. 73 — ТС, а ты на нём — водитель. Но правила для «механических» на тебя не распространяются, у тебя свои — ст. 43.")))

# ---------- 2. Двухколёсные ----------
P.append('<h2 id="dvuh">2. Велосипед, электросамокат, мопед, мотоцикл</h2>')
P.append('<p>Границы проведены по ' + gl("конструктивной скорости", "«максимальная скорость транспортного средства, определенная заводом-изготовителем» (ст. 5, п. 29) — не та, с которой вы едете") + ' и мощности/объёму мотора.</p>')
P.append(lq("Велосипед – транспортное средство, имеющее не менее двух колес и приводимое в движение лишь мускульной энергией сидящего на этом транспортном средстве лица, в частности с помощью педалей или ручных рычагов. Указанный термин не включает кресло-коляску. К велосипедам приравниваются велосипеды с подвесным двигателем.", "ст. 5, п. 22"))
P.append('<p>Мелочь перевода: в русском тексте «сидящего», в грузинском — მყოფი, «находящегося». Велосипедист, крутящий педали стоя, по-грузински точно на велосипеде; по-русски — <span class="unsure">наш вывод</span>, тоже: смысл в мускульной силе, а не в позе.</p>')
P.append(lq("Велосипед с подвесным двигателем – оснащенное двигателем двух- или трехколесное транспортное средство, конструктивная скорость которого не превышает 25 км/ч", "ст. 5, п. 28"))
P.append('<p>Дальше п. 28 перечисляет три варианта: мотор до 50 см³ и до 25 км/ч; электромотор до 4 кВт и до 25 км/ч; электромотор не больше 1 кВт, но тогда до 45 км/ч. Все они «велосипеды».</p>')
P.append(lq("Двухколесный электросамокат – самобалансирующееся двухколесное транспортное средство с одной осью, предназначенное для перевозки одного человека и приводимое в движение силой электроэнергии.", "ст. 5, п. 56"))
P.append('<p><b>Неясность.</b> «Самобалансирующееся… с одной осью» — это гироскутер или моноколесо-сегвей, у которых колёса стоят рядом на одной оси. Привычный городской электросамокат имеет два колеса одно за другим — <b>две оси</b> — и не балансирует сам. <span class="unsure">Наш вывод:</span> по букве п. 56 обычный самокат с мотором под определение не подходит; тогда он либо «велосипед с подвесным двигателем» (если ≤ 25 км/ч и ≤ 4 кВт), либо мопед. На практике и в билетах (№ 537) имеют в виду обычные самокаты. Сам закон их всё время называет двухколёсными электросамокатами, разрешает им тротуар и до 20 км/ч (ст. 43, пп. 12–13).</p>')
P.append(lq("Мопед – двух- или трехколесное механическое транспортное средство, конструктивная скорость которого превышает 25 км/ч, но не превышает 45 км/ч.", "ст. 5, п. 42"))
P.append('<p>Плюс ограничения мотора: до 50 см³, а электромотор — больше 1, но не больше 4 «кВт/ч». К трёхколёсным мопедам приравнены лёгкие квадроциклы (последняя фраза п. 42; сам лёгкий квадроцикл — п. 47).</p>')
P.append(lq("Мотоцикл – двухколесное механическое транспортное средство (с боковым прицепом или без него), рабочий объем двигателя которого превышает 50 см3 или (и) конструктивная скорость которого превышает 45 кВт/ч.", "ст. 5, п. 44"))
P.append('<p><b>Ошибка перевода.</b> Скорость в «кВт/ч» — бессмыслица: кВт — мощность, км/ч — скорость, а «кВт/ч» вообще не единица ни того, ни другого. В грузинском оригинале п. 44 стоит «45 კმ/სთ-ს» — <b>45 км/ч</b>. Та же ошибка в п. 53 (тихоходное ТС — «40 кВт/ч», в оригинале 40 км/ч) и в п. 43 (трицикл). Обратная путаница в п. 42 и п. 47: мощность там в «кВт/ч», а в оригинале — კვტ, просто кВт. Правильно читать: <b>скорость в км/ч, мощность в кВт</b>.</p>')
P.append(fig(fig_scale(), "Рис. 2. Конструктивная скорость решает класс. Велосипед с подвесным двигателем и мопед пересекаются по скорости 25–45 км/ч — различает их мощность электромотора (1 кВт)."))
P.append(lq("Тихоходное транспортное средство – оснащенное двигателем транспортное средство, конструктивная скорость которого не превышает 40 кВт/ч или которое не может превысить либо которому запрещается превышать указанную скорость", "ст. 5, п. 53"))
P.append('<p>Читаем «40 км/ч». Тихоходное — с мотором (повозка без мотора не тихоходное ТС) и не быстрее 40 по конструкции <i>или</i> по запрету (билет № 906).</p>')

P.append('<h3>Что из этого следует на дороге</h3>')
P.append(lq("Управлять велосипедом и двухколесным электросамокатом на дорогах разрешается лицам в возрасте не младше 14 лет, а управлять мопедом, снегоходом и мотосанями – лицам с 16-летнего возраста, только в соответствующем специальном шлеме.", "ст. 43, п. 1"))
P.append('<p>Велосипед и самокат — с 14 лет, мопед — с 16 (билет № 521). Мотоцикла в этом пункте нет — возраст для него ст. 43 не устанавливает.</p>')
P.append(lq("Водители мопедов, мотоциклов, двухколесных электросамокатов, велосипедов обязаны передвигаться на дорогах так, чтобы все колеса транспортного средства касались поверхности дороги.", "ст. 21, п. 11"))
P.append('<p>«Все колёса» — и у трёхколёсного мопеда тоже все три (билеты № 537, 826). Езда на заднем колесе запрещена.</p>')
P.append('<p><b>Пробелы.</b> Ступенчатая шкала оставляет дыры: двухколёсная техника с мотором, но до 25 км/ч и мощнее 4 кВт, — ни велосипед, ни мопед (мопед начинается с 25 км/ч), ни мотоцикл (≤ 45 и ≤ 50 см³). <span class="unsure">Наш вывод:</span> это просто механическое ТС без особого имени. А велосипед «до 25 км/ч и до 4 кВт» по мощности сильнее мопеда с 1 кВт — нестыковка самого п. 28.</p>')

# ---------- 3. Классы и прицепы ----------
P.append('<h2 id="klass">3. Лёгкий автомобиль, прицепы, маршрутные ТС</h2>')
P.append('<ul>'
         '<li><b>Лёгкий автомобиль</b> — разрешённая максимальная масса не более 3 500 кг и не больше 8 мест кроме водителя (п. 46, билет № 921).</li>'
         '<li><b>Автобус</b> — больше 8 сидячих мест кроме водителя (п. 1); <b>грузовой</b> — больше 3 500 кг (п. 71).</li>'
         '<li>' + gl("Прицеп", "«транспортное средство, предназначенное для его буксировки с помощью механического транспортного средства. Данный термин включает полуприцепы и прицепы-роспуски» (ст. 5, п. 39)") + '; <b>лёгкий прицеп</b> — разрешённая максимальная масса не больше 750 кг (п. 48, билет № 922).</li>'
         '<li><b>Автопоезд</b> — только грузовик с прицепом тяжелее 750 кг (п. 3). Легковушка с прицепом — не автопоезд.</li>'
         '<li><b>Маршрутное ТС</b> — едет «по установленному маршруту» и везёт пассажиров (п. 67): автобус, троллейбус, трамвай, маршрутка.</li></ul>')

P.append('<h3>Четыре массы — частая ловушка</h3>')
P.append('<table class="cmp"><thead><tr><th>Термин</th><th>Что входит</th><th>Кто определяет</th></tr></thead><tbody>'
         '<tr><td>Масса с нагрузкой (фактическая), п. 18</td><td>сейчас, с грузом, водителем и пассажирами</td><td>момент времени</td></tr>'
         '<tr><td>Масса без нагрузки, п. 19</td><td>без людей и груза, но с полным баком и инструментом</td><td>завод</td></tr>'
         '<tr><td>Разрешённая максимальная, п. 52</td><td>предел для гружёного ТС</td><td>орган страны регистрации</td></tr>'
         '<tr><td>Полная масса, п. 80</td><td>предел снаряжённого ТС с грузом и людьми</td><td>завод</td></tr></tbody></table>')
P.append(lq("Разрешенная максимальная масса (допустимый вес) – максимальная масса груженого транспортного средства, объявленная допустимой компетентным органом государства, в котором зарегистрировано транспортное средство.", "ст. 5, п. 52"))
P.append('<p>Ключ к билетам № 892, 893, 905, 925: «фактическая» — <i>сейчас</i>; «без нагрузки» — <i>завод, пустая, но с топливом</i>; «разрешённая» — <i>государство</i>; «полная» — <i>завод, предел</i>. Классы (лёгкий автомобиль, лёгкий прицеп, автопоезд) считаются по <b>разрешённой</b>, а не по фактической массе: пустой грузовик остаётся грузовиком.</p>')
P.append('<p><b>Двойственность.</b> Разрешённая (п. 52) и полная (п. 80) масса описывают почти одно — предел гружёного ТС, — но устанавливают их разные органы. Какая важнее, если цифры разошлись, ст. 5 не говорит; классы привязаны к разрешённой.</p>')

# ---------- 4. Трамвай ----------
P.append('<h2 id="tram">4. Рельсовые ТС на перекрёстке</h2>')
P.append('<p>Почему трамвай отдельно? Потому что у него особое право на перекрёстке равнозначных дорог. Напомним условие: перекрёсток нерегулируемый, если светофора нет, он не работает или мигает жёлтым, и регулировщика нет (ст. 36, п. 2).</p>')
P.append(lq("на перекрестке равнозначных дорог водители безрельсовых транспортных средств обязаны уступать дорогу приближающимся к ним справа транспортным средствам. Этим же правилом должны руководствоваться между собой и водители рельсовых транспортных средств. На таких перекрестках рельсовые транспортные средства имеют преимущество перед безрельсовыми транспортными средствами, независимо от направления их дальнейшего движения;", "ст. 36, п. 4 «в»"))
P.append('<p>Три правила в одном пункте:</p><ol class="parts">'
         '<li>Безрельсовые между собой — помеха справа (урок 3).</li>'
         '<li>Трамваи между собой — тоже помеха справа.</li>'
         '<li>Трамвай против безрельсового — <b>трамвай первым</b>, откуда бы он ни ехал и куда бы ни поворачивал.</li></ol>')
P.append(fig(fig_tram(), "Рис. 3. Трамвай подъезжает слева от автомобиля A. По правилу правой руки он бы уступал, но п. 4 «в» даёт рельсовому ТС преимущество — A ждёт."))
P.append('<p>Важно, где это <b>не</b> работает: на перекрёстке неравнозначных дорог трамвай на второстепенной уступает машинам на главной (п. 4 «а» касается всех «транспортных средств»), а при светофоре — сигналы. Преимущество трамвая — только «на таких перекрестках», то есть равнозначных.</p>')
P.append(chat(("a", "А если светофор мигает жёлтым — трамвай всё равно первый?"),
              ("t", "Если дороги равнозначные — да. Мигающий жёлтый делает перекрёсток нерегулируемым, а дальше — п. 4 «в». Это билет № 75.")))

# ---------- Неладно ----------
P.append('<h2 id="flaws">Что в определениях неладно</h2>')
P.append('<ul class="flaws">'
         '<li>Скорость в «кВт/ч» (пп. 43, 44, 53) и мощность в «кВт/ч» (пп. 42, 47) — ошибки русского перевода; в грузинском км/ч (კმ/სთ) и кВт (კვტ).</li>'
         '<li>П. 56 описывает самобалансирующийся одноосный аппарат; обычный электросамокат — двухосный (наш вывод: формально выпадает).</li>'
         '<li>П. 28 допускает «велосипед» с электромотором 4 кВт — мощнее мопеда; между классами есть дыры.</li>'
         '<li>«Сидящего» (RU) против «находящегося» (KA) в п. 22.</li>'
         '<li>Разрешённая и полная массы почти совпадают по смыслу, а определяют их разные органы.</li></ul>')

# ---------- Ситуации ----------
P.append('<h2 id="sit">Две ситуации</h2>')
P.append('<h3>Ситуация 1. Подарок на 15 лет</h3>')
P.append(chat(("m", "Племяннику 15, хотим подарить мопед. Он же почти велосипед?"),
              ("t", "Нет. Мопед — механическое ТС, и с 16 лет, в шлеме. Электровелосипед до 25 км/ч и до 4 кВт — по закону велосипед, на нём с 14.")))
P.append('<p>Разбор: по ст. 43, п. 1 мопед — с 16 лет и только в шлеме; велосипед с подвесным двигателем приравнен к велосипеду (ст. 5, п. 22), а велосипед — с 14.</p>')
P.append('<h3>Ситуация 2. Трамвай слева</h3>')
P.append(chat(("a", "Еду прямо по равнозначному перекрёстку, справа никого, слева трамвай поворачивает направо — в мою сторону. Я по правилу правой руки еду первой?"),
              ("t", "Нет. Трамвай имеет преимущество «независимо от направления их дальнейшего движения». Ты ждёшь.")))
P.append('<p class="note info">Дальше — билеты: классы и массы (№ 921, 922, 906, 905, 892, 893, 925), возраст и колёса (№ 521, 537, 826) и четыре перекрёстка с трамваем (№ 47, 53, 69, 75).</p>')

P.append("<!--AFTER-TICKETS-->")
P.append(chat(("m", "Запомнил: механическое — с мотором, кроме самоката, велика с мотором и трамвая. Скорость — км/ч, сколько бы ни писали кВт/ч."),
              ("a", "А трамвай на равнозначном — всегда первый."),
              ("t", "Словарь закончили. Дальше — действия: обгон, остановка, стоянка, «уступить дорогу». Там определения уже прямо решают билеты.")))

BODY = "\n".join(P) + "\n"


def render() -> str:
    return BODY
